def set_angle(angle):
    # 角度をパルス幅 (ns) に変換
    pulse_ns = int(500000 + (angle / 180) * 2000000)
    servo.duty_ns(pulse_ns)

def set_angle2(angle):
    # 角度をパルス幅 (ns) に変換
    pulse_ns = int(500000 + (angle / 180) * 2000000)
    servo2.duty_ns(pulse_ns)
    
def openball():
    set_angle2(180)
    set_angle(100)

def closeball():
    set_angle2(80)
    set_angle(10)

def closeball2():
    # set_angle2(80)
    set_angle(30)

def manyball():
    for i in range(40):
        openball()
        utime.sleep(0.3)
        closeball2()
        utime.sleep(0.3)
    closeball()

def singleball():
    openball()
    utime.sleep(3)
    closeball()
        
def p(v, l=20, c=""):
    n = max(0, min(1, v / 516))  # 10bit ADCなので最大値は1023
    f = int(n * l)
    print(f"\r[{'|'*f}{' '*(l-f)}] {int(n*100)}% ({v})", end=f"{"    !!LINE!!    " if v < shikii_line else ""}{c}")
    
def upsound():
    PWM_A.duty_u16(1000)
    PWM_B.duty_u16(1000)
    PWM_C.duty_u16(1000)
    PWM_D.duty_u16(1000)
    frequencies = [262, 294, 330, 10000]
    for f in frequencies:
        PWM_A.freq(f)
        PWM_B.freq(f)
        PWM_C.freq(f)
        PWM_D.freq(f)
        utime.sleep(0.05)

def downsound():
    PWM_A.duty_u16(2000)
    PWM_B.duty_u16(2000)
    PWM_C.duty_u16(2000)
    PWM_D.duty_u16(2000)
    frequencies = [10000, 262, 294, 330]
    frequencies.reverse()
    for f in frequencies:
        PWM_A.freq(f)
        PWM_B.freq(f)
        PWM_C.freq(f)
        PWM_D.freq(f)
        utime.sleep(0.05)
        
def mtsound():
    PWM_A.duty_u16(1000)
    PWM_B.duty_u16(1000)
    PWM_C.duty_u16(1000)
    PWM_D.duty_u16(1000)
    frequencies = [262, 330, 392, 523, 494, 440, 349, 294, 10000]
    for f in frequencies:
        PWM_A.freq(f)
        PWM_B.freq(f)
        PWM_C.freq(f)
        PWM_D.freq(f)
        utime.sleep(0.05)
    
