def normalTrace():
    global lost, latestmove, losted
    if mcp.read_adc(1) < shikii_line:
        o.move(-yoko,mae,spd,-senkai)
        lost = False
        latestmove = "r"
    elif mcp.read_adc(2) < shikii_line:
        o.move(yoko,mae,spd,senkai)
        lost = False
        latestmove = "l"
    else:
        o.move(0,mae,spd,0)
        if not lost:
            lost = True
            losted = utime.ticks_ms()
                        
def kstCheck_T():
    global kst_lft,kst_rig,kst_tik,skwww
    kst_lft -= 1
    kst_rig -= 1
    kst_tik -= 1
    # d1 = [mcp.read_adc(1) > shikii_line, mcp.read_adc(2) > shikii_line, mcp.read_adc(3) > shikii_line]
    # d2 = [mcp.read_adc(0) > shikii_line, mcp.read_adc(1) > shikii_line, mcp.read_adc(2) > shikii_line]
    d1,d2 = [],[]
    if mcp.read_adc(0)<(shikii_line+50) and all(d1):
        kst_lft = kst
    if mcp.read_adc(3)<(shikii_line+50) and all(d2):
        kst_rig = kst
    # print(kst_lft,kst_rig,kst_tik)
    if kst_lft > 0 and kst_rig > 0 and kst_tik < 1:
        skwww = "T"
        return True
    return False

def kstMove():
    global kst_rig,kst_lft,kst_tik,losted,skwww,kstcount
    if turn == 0 and kstcount == 3:
        o.move(0,1,30000,0)
        utime.sleep(0.5)
        o.stop()
        utime.sleep(10000)
    upsound()
    o.move(0,kstzzny,10000,0)
    utime.sleep_ms(kszzntime)
    o.move(0.1,ksty*kstmv,5000,kstsnk*kstmv)
    utime.sleep_ms(kstime)
    while not mcp.read_adc(2) < shikii_line:
        pass
    kst_rig,kst_lft,losted=0,0,utime.ticks_ms()
    kst_tik = 600
    skwww = ""
    kstcount += 1
        
    
def kstCheck_skw_legacy():
    global kst_lft,kst_rig,kst_tik
    if not lost:
        if mcp.read_adc(0)<(shikii_line):
            return "lft"
        if mcp.read_adc(3)<(shikii_line):
            return "rig"
        print("NO SKW")
    return False

def kstCheck_skw():
    global kst_lft, kst_rig, kst_tik
    # 1. 左側（0番）がト字（左分岐）を見つけたとき
    if mcp.read_adc(0) < shikii_line:
        # ★反対側の中心センサー（2番）がすでに黒を見つけていたら、
        # 車体が斜めにねじれているかV字の別ラインなので「偽物」として弾く！
        # if mcp.read_adc(2) < shikii_line or mcp.read_adc(3) < shikii_line:
        #     print("NO SKW")
        #     return False
        return "lft"
    # 2. 右側（3番）がト字（右分岐）を見つけたとき
    if mcp.read_adc(3) < shikii_line:
        # ★反対側の中心センサー（1番）がすでに黒を見つけていたら弾く！
        # if mcp.read_adc(1) < shikii_line or mcp.read_adc(0) < shikii_line:
        #     print("NO SKW")
        #     return False
        return "rig"        
    print("NO SKW")
    return False

def kstMove_skw(dir:str):
    global kst_rig,kst_lft,kst_tik,losted,skwww,skwtime,kstcount
    if turn == 0 and kstcount == 3:
        o.move(0,1,30000,0)
        utime.sleep(0.5)
        o.stop()
        utime.sleep(10000)
    o.move(0,kstzzny,10000,0)
    for i in range(int(kszzntime_skw)):
        if kstCheck_T():
            kstMove()
            return
        utime.sleep_ms(1)
    o.stop()
    if dir == "lft":
        mtsound()
        o.move(0.1,ksty*kstmv,10000,kstsnk*-1)
        utime.sleep_ms(kstime_skw)
        while not mcp.read_adc(1) < shikii_line:
            pass
    else:
        apsound()
        o.move(0.1,ksty*kstmv,10000,kstsnk*1)
        utime.sleep_ms(kstime_skw)
        while not mcp.read_adc(2) < shikii_line:
            pass
    kst_rig,kst_lft,losted=0,0,utime.ticks_ms()
    kst_tik = 600
    skwtime = 0
    skwww = ""
    kstcount += 1
    
def sideTrace():
    global lost, latestmove, side, losted
    side = True

    # ★ 「and skwtime == 0」を削るだけ。skwtimeは絶対にリセットしない！
    if lost: 
        if mcp.read_adc(3) < shikii_line:
            o.move(0, 0, spd, senkai * 3)
            utime.sleep_ms(10)
            o.move(0.5, 0, spd, 0)
            latestmove = "l"
            losted = utime.ticks_ms()
            side = True
            
        elif mcp.read_adc(0) < shikii_line:
            o.move(0, -0.1, spd, -senkai * 3)
            utime.sleep_ms(10)
            o.move(-0.5, 0, spd, 0)
            latestmove = "r"
            losted = utime.ticks_ms()
            side = True

        if mcp.read_adc(1) < shikii_line or mcp.read_adc(2) < shikii_line:
            lost = False

def lostCheck():
    global losted, lost
    if lost and utime.ticks_diff(utime.ticks_ms(), losted) > lostime and kst_tik < 0:
        o.stop()
        o.move(0,0,5000,-1)
        while True:
            # if all(mcp.read_adc(i) > shikii_line for i in range(4)):
            if mcp.read_adc(1) < shikii_line or mcp.read_adc(2) < shikii_line:
                lost = False
                return False
    return False

def distCheck():
    global dist,dist_new
    dist_new = hcsr.distance()
    a = all([dist_new > 1, dist_new < shikii_dis, abs(dist_new - dist) < 5, dist_new > 0.5])
    dist = hcsr.distance()
    return a

def GoalCheckMove():
    o.stop()
    fls = 0
    for i in range(10):
        if not distCheck():
            fls += 1
        if fls >= 2:
            return
        utime.sleep_ms(50)
    o.move(0,1,10000,0)
    utime.sleep_ms(200)
    o.stop()
    if turn == 0:
        singleball()
    else:
        manyball()
    o.move(0,-1,10000,0)
    utime.sleep_ms(300)
    o.move(0.3,-0.3,15000,1)
